// Generated by philote from page /books. Do not edit.
import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import { books } from "@/lib/api";
import { must } from "@/lib/backend";
import { readBookCard } from "@/lib/reads";

import BookCard from "@/components/common/book-card";

export const metadata: Metadata = { title: "Books" };

export default function Page() {
    return (
        <main className="flex-1 p-8">
            <div className="mx-auto max-w-4xl space-y-6">
                <h1 className="font-heading text-4xl">{"Books"}</h1>
                <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                    <Records />
                </Suspense>
            </div>
        </main>
    );
}

async function Records() {
    await connection();
    const records = await must(books.list());
    if (records.length === 0) {
        return <p className="text-muted-foreground">{"No books yet."}</p>;
    }
    const items = await Promise.all(records.map(readBookCard));
    return (
        <div className="grid gap-4 md:grid-cols-2">
            {items.map((item) => (
                <BookCard key={item.book.id} {...item} />
            ))}
        </div>
    );
}
